#pragma once
#include "rinkfit/joint_al.hpp"
namespace rinkfit {
struct JointReplayArtifactFile {std::string relative,sha256;std::uintmax_t bytes=0;};
struct JointReplayArtifactMemo {std::string state_token,source_sha256;std::filesystem::path directory;eventio::Json value_report;std::vector<JointReplayArtifactFile>files;};
inline std::vector<JointReplayArtifactFile> joint_replay_artifact_inventory(const std::filesystem::path&directory,const eventio::Json&report){std::vector<JointReplayArtifactFile>files;for(auto i=report.at("files").begin();i!=report.at("files").end();++i)files.push_back({i.key(),i.value().at("sha256"),i.value().at("size_bytes")});const auto manifest=eventio::read_json((directory/"explicit_nuisance/manifest.json").string());for(auto i=manifest.at("files").begin();i!=manifest.at("files").end();++i)files.push_back({"explicit_nuisance/"+i.key(),i.value().at("sha256"),i.value().at("size_bytes")});for(const auto&name:{"value_report.json","explicit_nuisance/manifest.json"})files.push_back({name,eventio::file_sha256(directory/name),std::filesystem::file_size(directory/name)});return files;}
inline eventio::Json link_verified_joint_replay_artifacts(const std::filesystem::path&source,const std::filesystem::path&target,const std::vector<JointReplayArtifactFile>&files){if(std::filesystem::exists(target))throw std::runtime_error("immutable diagnostic target exists");for(const auto&f:files){const auto rel=std::filesystem::path(f.relative);if(rel.is_absolute()||f.relative.find("..")!=std::string::npos||!std::filesystem::is_regular_file(source/rel)||std::filesystem::file_size(source/rel)!=f.bytes||eventio::file_sha256(source/rel)!=f.sha256)throw std::runtime_error("unchanged-state replay artifact is not the original immutable file: "+f.relative);}std::filesystem::create_directories(target);std::size_t links=0,copies=0;std::uintmax_t linked_bytes=0;for(const auto&f:files){const auto from=source/f.relative,to=target/f.relative;std::filesystem::create_directories(to.parent_path());std::error_code ec;std::filesystem::create_hard_link(from,to,ec);if(ec){std::filesystem::copy_file(from,to);++copies;}else{++links;linked_bytes+=f.bytes;}}return {{"source_directory",source.string()},{"target_directory",target.string()},{"verified_files",files.size()},{"hard_linked_files",links},{"copied_files_fallback",copies},{"duplicate_physical_bytes_avoided",linked_bytes},{"all_source_artifact_bytes_SHA_verified_before_link",true},{"complete_checkpoints_and_outer_receipts_never_linked",true}};}
inline eventio::Json export_joint_replay_artifacts(JointALBuilder&builder,const StateSnapshot&state,const std::filesystem::path&out,JointReplayArtifactMemo*memo,bool require_independent_frozen_export=false,bool exact_checkpoint_model=false){if(!memo)throw std::runtime_error("missing local diagnostic memo");if(!require_independent_frozen_export&&(!exact_checkpoint_model||(memo->value_report.is_object()&&memo->value_report.value("exact_checkpoint_model_blocks",false)))&&memo->state_token==state.token()&&memo->source_sha256==builder.core.packet.source_hash&&!memo->directory.empty()){auto receipt=link_verified_joint_replay_artifacts(memo->directory,out,memo->files);receipt["schema"]="rinkfit.exact_unchanged_state_diagnostic_artifact_reuse.v1";receipt["state_token"]=state.token();receipt["source_packet_sha256"]=builder.core.packet.source_hash;receipt["final_frozen_independent_acceptance_claimed"]=false;eventio::atomic_json(out/"diagnostic_reuse.json",receipt);return memo->value_report;}auto report=builder.core.replay(out);if(exact_checkpoint_model){eventio::atomic_json(out/"model.json",builder.core.model.exact_json());const auto digest=eventio::file_sha256(out/"model.json");report["model_sha256"]=digest;report["files"]["model.json"]={{"sha256",digest},{"size_bytes",std::filesystem::file_size(out/"model.json")}};report["exact_checkpoint_model_blocks"]=true;eventio::atomic_json(out/"value_report.json",report);}builder.export_explicit_nuisance(out/"explicit_nuisance");memo->state_token=state.token();memo->source_sha256=builder.core.packet.source_hash;memo->directory=out;memo->value_report=report;memo->files=joint_replay_artifact_inventory(out,report);return report;}
}
